<script setup lang="ts">
import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,computed} from 'vue';import {pmsApi} from './api';const tablePage=ref(1),tableSize=ref(10),search=ref('');const shown=computed(()=>rows.value.filter(row=>Object.values(row).filter(v=>typeof v==='string').join(' ').toLowerCase().includes(search.value.toLowerCase())));const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const data=ref<any>(null),rows=ref<any[]>([]),busy=ref(false),error=ref(''),filters=ref({user_id:'',project_id:'',start_date:'',end_date:''});function exportUrl(format:string){return '/pms/api/work-logs/export/'+format+'?'+new URLSearchParams(filters.value);}
async function copyLogs(){try{await navigator.clipboard.writeText([Object.values(columns).join('\t'),...rows.value.map(r=>Object.keys(columns).map(k=>r[k]??'').join('\t'))].join('\n'));}catch(e){error.value=(e as Error).message;}}
async function load(){busy.value=true;try{const d=await pmsApi('work-logs?'+new URLSearchParams(filters.value),'','GET',undefined,true);rows.value=d.data;error.value='';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}onMounted(async()=>{try{data.value=(await pmsApi('work-logs')).data;await load();}catch(e){error.value=(e as Error).message;}});const columns:any={project:'Project',type:'Type',title:'Title',status:'Status',user:'User',time_spent:'Invested Time',created_at:'Start Date',due_date:'Due Date',assigned_by:'Assigned by'};
</script><template><div class="admin-section-heading"><div><h2>Work Logs</h2><p class="text-muted">Review completed work and tracked time by employee, project and date.</p></div><span class="badge bg-label-primary">Time and activity report</span></div><p v-if="error" class="notice admin-error">{{error}}</p><form class="card p-3 my-3 pms-report-filters" @submit.prevent="load"><div class="editor-actions"><label>User<select v-model="filters.user_id"><option value="">All users</option><option v-for="u in data?.users" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>Project<select v-model="filters.project_id"><option value="">All projects</option><option v-for="p in data?.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>From<input type="date" v-model="filters.start_date"></label><label>To<input type="date" v-model="filters.end_date" :min="filters.start_date"></label><div class="pms-filter-actions"><button type="button" class="button" @click="filters={user_id:'',project_id:'',start_date:'',end_date:''};load()">Reset</button><button class="button primary" :disabled="busy">Apply Filter</button></div></div></form><p v-if="busy" role="status">Loading logs...</p><div class="pms-table-card"><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search"><details class="pms-export-menu"><summary class="button">Export</summary><div><button @click="copyLogs">Copy</button><a v-for="f in ['csv','xlsx','pdf']" :key="f" :href="exportUrl(f)">{{f.toUpperCase()}}</a></div></details></PmsTableControls><table class="pms-table"><thead><tr><th v-for="(label,key) in columns" :key="key" scope="col">{{label}}</th></tr></thead><tbody><tr v-for="(row,index) in paged" :key="index"><td v-for="(_,key) in columns" :key="key">{{row[key]}}</td></tr><tr v-if="!rows.length"><td colspan="9">No work logs match these filters.</td></tr></tbody></table><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div></template>